import React, { useEffect, useMemo, useState } from "react";

import axios from "axios";

import {
  AppBar,
  Toolbar,
  Typography,
  Box,
  Button,
  Container,
  Grid,
  Card,
  CardContent,
  CardMedia,
  Chip,
  IconButton,
  Drawer,
  List,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Divider,
  Badge,
  TextField,
  InputAdornment,
  Alert,
  CircularProgress,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Rating,
} from "@mui/material";

import {
  Menu as MenuIcon,
  Restaurant,
  ShoppingCart,
  ReceiptLong,
  RateReview,
  Person,
  Logout,
  Search,
  Add,
  Remove,
  Home,
} from "@mui/icons-material";

const categories = [
  "All",
  "Breakfast",
  "Lunch",
  "Snacks",
  "Beverages",
  "Dessert",
];

const UserDashboard = ({ user, onLogout }) => {
  const [menuItems, setMenuItems] = useState([]);
  const [loadingMenu, setLoadingMenu] = useState(true);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [activePage, setActivePage] = useState("home");

  const [search, setSearch] = useState("");
  const [category, setCategory] = useState("All");

  const [cart, setCart] = useState([]);

  const [orders, setOrders] = useState([]);
  const [loadingOrders, setLoadingOrders] = useState(false);

  // =========================
  // REVIEW STATE
  // =========================
  const [reviews, setReviews] = useState([]);
  const [loadingReviews, setLoadingReviews] = useState(false);
  const [reviewDialogOpen, setReviewDialogOpen] = useState(false);
  const [selectedOrder, setSelectedOrder] = useState(null);
  const [selectedFood, setSelectedFood] = useState(null);
  const [selectedRating, setSelectedRating] = useState(0);
  const [reviewComment, setReviewComment] = useState("");
  const [submittingReview, setSubmittingReview] = useState(false);

  const [orderMessage, setOrderMessage] = useState("");
  const [error, setError] = useState("");

  // =========================
  // LOAD MENU
  // =========================
  const loadMenu = async () => {
    try {
      setLoadingMenu(true);

      const response = await axios.get("/api/menu");

      const items = Array.isArray(response.data)
        ? response.data
        : response.data.menuItems || [];

      setMenuItems(items);
    } catch (err) {
      console.error("Error loading menu:", err);

      setError(
        err.response?.data?.message ||
        "Unable to load menu."
      );
    } finally {
      setLoadingMenu(false);
    }
  };

  // =========================
  // LOAD ORDERS
  // =========================
  const loadOrders = async () => {
    try {
      setLoadingOrders(true);
      setError("");

      const token = localStorage.getItem("token");

      if (!token) {
        setError(
          "Your login session has expired. Please login again."
        );
        return;
      }

      const response = await axios.get(
        "/api/orders/my",
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      const apiOrders = Array.isArray(
        response.data
      )
        ? response.data
        : response.data.orders || [];

      const myOrders = apiOrders.map(
        (order) => {
          const totalQuantity =
            (order.items || []).reduce(
              (total, item) =>
                total + item.quantity,
              0
            );

          return {
            ...order,

            itemName: (order.items || [])
              .map(
                (item) =>
                  `${item.name} × ${item.quantity}`
              )
              .join(", "),

            quantity: totalQuantity,

            price:
              totalQuantity > 0
                ? order.totalAmount /
                totalQuantity
                : 0,
          };
        }
      );

      setOrders(myOrders);
    } catch (err) {
      console.error(
        "Error loading orders:",
        err
      );

      setError(
        err.response?.data?.message ||
        "Unable to load your orders."
      );
    } finally {
      setLoadingOrders(false);
    }
  };

  // =========================
  // LOAD MY REVIEWS
  // =========================
  const loadReviews = async () => {
    try {
      setLoadingReviews(true);

      const token =
        localStorage.getItem("token");

      if (!token) {
        return;
      }

      const response = await axios.get(
        "/api/reviews/my",
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      setReviews(
        response.data?.reviews || []
      );
    } catch (err) {
      console.error(
        "Error loading reviews:",
        err
      );

      setError(
        err.response?.data?.message ||
        "Unable to load reviews."
      );
    } finally {
      setLoadingReviews(false);
    }
  };

  // =========================
  // CHECK WHETHER FOOD
  // IS ALREADY REVIEWED
  // =========================
  const isFoodReviewed = (
    orderId,
    menuItemId
  ) => {
    return reviews.some((review) => {
      const reviewOrderId =
        review.orderId?._id ||
        review.orderId;

      const reviewMenuItemId =
        review.menuItemId?._id ||
        review.menuItemId;

      return (
        String(reviewOrderId) ===
        String(orderId) &&
        String(reviewMenuItemId) ===
        String(menuItemId)
      );
    });
  };

  // =========================
  // OPEN REVIEW DIALOG
  // =========================
  const openReviewDialog = (
    order,
    food
  ) => {
    setSelectedOrder(order);
    setSelectedFood(food);
    setSelectedRating(0);
    setReviewComment("");
    setError("");
    setReviewDialogOpen(true);
  };

  // =========================
  // CLOSE REVIEW DIALOG
  // =========================
  const closeReviewDialog = () => {
    setReviewDialogOpen(false);

    setSelectedOrder(null);
    setSelectedFood(null);

    setSelectedRating(0);
    setReviewComment("");
  };

  // =========================
  // SUBMIT REVIEW
  // =========================
  const submitReview = async () => {
    if (
      !selectedOrder ||
      !selectedFood
    ) {
      setError(
        "Please select a food item."
      );
      return;
    }

    if (selectedRating < 1) {
      setError(
        "Please select a rating from 1 to 5 stars."
      );
      return;
    }

    try {
      setSubmittingReview(true);
      setError("");
      setOrderMessage("");

      const token =
        localStorage.getItem("token");

      if (!token) {
        setError(
          "Your login session has expired. Please login again."
        );
        return;
      }

      await axios.post(
        "/api/reviews",
        {
          orderId:
            selectedOrder._id,

          menuItemId:
            selectedFood.menuItemId,

          rating: selectedRating,

          comment:
            reviewComment.trim(),
        },
        {
          headers: {
            Authorization:
              `Bearer ${token}`,
          },
        }
      );

      closeReviewDialog();

      setOrderMessage(
        "Review submitted successfully!"
      );

      await loadReviews();
    } catch (err) {
      console.error(
        "Submit review error:",
        err
      );

      setError(
        err.response?.data?.message ||
        "Unable to submit review."
      );
    } finally {
      setSubmittingReview(false);
    }
  };

  // =========================
  // INITIAL LOAD
  // =========================
  useEffect(() => {
    loadMenu();
    loadOrders();
    loadReviews();
  }, []);

  // =========================
  // SEARCH + CATEGORY FILTER
  // =========================
  const filteredMenu = useMemo(() => {
    const normalizeSearch = (
      value
    ) => {
      const text = value
        .trim()
        .toLowerCase();

      const corrections = {
        spicey: "spicy",
        spciey: "spicy",
        spciy: "spicy",
        cakes: "cake",
        sweets: "sweet",
        drinks: "drink",
        beverages: "drink",
        snacks: "snack",
        desserts: "dessert",
      };

      return (
        corrections[text] || text
      );
    };

    const searchText =
      normalizeSearch(search);

    const searchAliases = {
      spicy: [
        "spicy",
        "hot",
        "masala",
        "chilli",
        "chili",
        "pepper",
        "spiced",
      ],

      sweet: [
        "sweet",
        "dessert",
        "cake",
        "chocolate",
        "ice cream",
        "gulab",
        "pastry",
      ],

      cake: [
        "cake",
        "dessert",
        "chocolate",
        "sweet",
        "pastry",
      ],

      drink: [
        "drink",
        "beverage",
        "tea",
        "coffee",
        "juice",
        "lassi",
        "milkshake",
        "shake",
        "soft drink",
      ],

      snack: [
        "snack",
        "samosa",
        "pakora",
        "puff",
        "sandwich",
        "fried",
      ],

      breakfast: [
        "breakfast",
        "dosa",
        "idli",
        "vada",
        "upma",
        "poha",
        "puri",
      ],

      lunch: [
        "lunch",
        "biryani",
        "rice",
        "meal",
        "thali",
        "curry",
      ],
    };

    return menuItems.filter(
      (item) => {
        const itemName = (
          item.name || ""
        ).toLowerCase();

        const itemCategory = (
          item.category || ""
        ).toLowerCase();

        const itemDescription = (
          item.description || ""
        ).toLowerCase();

        const itemKeywords =
          Array.isArray(
            item.keywords
          )
            ? item.keywords
              .join(" ")
              .toLowerCase()
            : "";

        const searchableText = `
          ${itemName}
          ${itemCategory}
          ${itemDescription}
          ${itemKeywords}
        `.toLowerCase();

        let matchesSearch =
          searchText === "" ||
          searchableText.includes(
            searchText
          );

        if (
          searchText &&
          searchAliases[searchText]
        ) {
          matchesSearch =
            searchAliases[
              searchText
            ].some((keyword) =>
              searchableText.includes(
                keyword
              )
            );
        }

        const matchesCategory =
          category === "All" ||
          item.category === category;

        return (
          matchesSearch &&
          matchesCategory
        );
      }
    );
  }, [
    menuItems,
    search,
    category,
  ]);

  // =========================
  // ADD TO CART
  // =========================
  const addToCart = (item) => {
    setCart((previousCart) => {
      const existing =
        previousCart.find(
          (cartItem) =>
            cartItem.name ===
            item.name
        );

      if (existing) {
        return previousCart.map(
          (cartItem) =>
            cartItem.name ===
              item.name
              ? {
                ...cartItem,
                quantity:
                  cartItem.quantity +
                  1,
              }
              : cartItem
        );
      }

      return [
        ...previousCart,
        {
          ...item,
          quantity: 1,
        },
      ];
    });
  };

  // =========================
  // INCREASE QUANTITY
  // =========================
  const increaseQuantity = (
    name
  ) => {
    setCart((previousCart) =>
      previousCart.map(
        (item) =>
          item.name === name
            ? {
              ...item,
              quantity:
                item.quantity + 1,
            }
            : item
      )
    );
  };

  // =========================
  // DECREASE QUANTITY
  // =========================
  const decreaseQuantity = (
    name
  ) => {
    setCart((previousCart) =>
      previousCart
        .map((item) =>
          item.name === name
            ? {
              ...item,
              quantity:
                item.quantity - 1,
            }
            : item
        )
        .filter(
          (item) =>
            item.quantity > 0
        )
    );
  };

  const cartCount =
    cart.reduce(
      (total, item) =>
        total + item.quantity,
      0
    );

  const cartTotal =
    cart.reduce(
      (total, item) =>
        total +
        item.price *
        item.quantity,
      0
    );

  // =========================
  // PLACE ORDER
  // =========================
  const placeOrder = async () => {
    if (cart.length === 0) {
      setError(
        "Your cart is empty."
      );
      return;
    }

    try {
      setError("");
      setOrderMessage("");

      const token =
        localStorage.getItem("token");

      if (!token) {
        setError(
          "Your login session has expired. Please login again."
        );
        return;
      }

      const response =
        await axios.post(
          "/api/orders",
          {
            items: cart.map(
              (item) => ({
                menuItemId:
                  item._id,
                quantity:
                  item.quantity,
              })
            ),

            paymentMethod:
              "Cash",

            specialRequests: "",
          },
          {
            headers: {
              Authorization:
                `Bearer ${token}`,
            },
          }
        );

      setCart([]);

      const tokenNumber =
        response.data?.order
          ?.orderNumber ||
        response.data
          ?.orderNumber ||
        "Generated";

      setOrderMessage(
        `Order placed successfully! Your Token: ${tokenNumber}`
      );

      await loadOrders();

      setActivePage(
        "orders"
      );
    } catch (err) {
      console.error(
        "Order error:",
        err
      );

      setError(
        err.response?.data?.message ||
        "Unable to place order."
      );
    }
  };

  const handleLogout = () => {
    onLogout();
  };

  // =========================
  // HOME
  // =========================
  const renderHome = () => (
    <>
      <Box
        sx={{
          mb: 4,
          p: 4,
          borderRadius: 4,
          background:
            "linear-gradient(135deg, #2E7D32 0%, #4CAF50 100%)",
          color: "white",
        }}
      >
        <Typography
          variant="h4"
          sx={{
            fontWeight: 800,
            mb: 1,
          }}
        >
          Welcome, {user.name}
        </Typography>

        <Typography variant="h6">
          What would you like to eat today?
        </Typography>
      </Box>

      <Typography
        variant="h5"
        sx={{
          fontWeight: 800,
          mb: 2,
          color: "#2E7D32",
        }}
      >
        Popular Menu
      </Typography>

      <Grid container spacing={3}>
        {menuItems
          .slice(0, 4)
          .map((item) => (
            <Grid
              item
              xs={12}
              sm={6}
              md={3}
              key={item.name}
            >
              <Card
                sx={{
                  height: "100%",
                  borderRadius: 3,
                  overflow: "hidden",
                  boxShadow:
                    "0 4px 15px rgba(0,0,0,0.08)",
                }}
              >
                <CardMedia
                  component="img"
                  height="180"
                  image={item.image}
                  alt={item.name}
                />

                <CardContent>
                  <Typography
                    variant="h6"
                    sx={{
                      fontWeight: 700,
                    }}
                  >
                    {item.name}
                  </Typography>

                  <Typography
                    color="text.secondary"
                    sx={{ mb: 2 }}
                  >
                    ₹{item.price}
                  </Typography>

                  <Button
                    fullWidth
                    variant="contained"
                    startIcon={<Add />}
                    onClick={() =>
                      addToCart(item)
                    }
                    sx={{
                      background:
                        "linear-gradient(135deg, #2E7D32, #4CAF50)",
                    }}
                  >
                    Add to Cart
                  </Button>
                </CardContent>
              </Card>
            </Grid>
          ))}
      </Grid>
    </>
  );

  // =========================
  // MENU
  // =========================
  const renderMenu = () => (
    <>
      <Typography
        variant="h4"
        sx={{
          fontWeight: 800,
          color: "#2E7D32",
          mb: 3,
        }}
      >
        Food Menu
      </Typography>

      <TextField
        fullWidth
        placeholder="Search food..."
        value={search}
        onChange={(e) =>
          setSearch(e.target.value)
        }
        sx={{ mb: 2 }}
        InputProps={{
          startAdornment: (
            <InputAdornment position="start">
              <Search />
            </InputAdornment>
          ),
        }}
      />

      <Box
        sx={{
          display: "flex",
          gap: 1,
          flexWrap: "wrap",
          mb: 4,
        }}
      >
        {categories.map(
          (item) => (
            <Button
              key={item}
              variant={
                category === item
                  ? "contained"
                  : "outlined"
              }
              onClick={() =>
                setCategory(item)
              }
              sx={{
                borderRadius: 5,
                color:
                  category === item
                    ? "white"
                    : "#2E7D32",
                borderColor:
                  "#2E7D32",
                backgroundColor:
                  category === item
                    ? "#2E7D32"
                    : "transparent",
              }}
            >
              {item}
            </Button>
          )
        )}
      </Box>

      {loadingMenu ? (
        <Box
          sx={{
            textAlign: "center",
            py: 5,
          }}
        >
          <CircularProgress />
        </Box>
      ) : (
        <Grid container spacing={3}>
          {filteredMenu.map(
            (item) => (
              <Grid
                item
                xs={12}
                sm={6}
                md={4}
                key={item.name}
              >
                <Card
                  sx={{
                    height: "100%",
                    borderRadius: 3,
                    overflow: "hidden",
                  }}
                >
                  <CardMedia
                    component="img"
                    height="210"
                    image={item.image}
                    alt={item.name}
                  />

                  <CardContent>
                    <Box
                      sx={{
                        display: "flex",
                        justifyContent:
                          "space-between",
                        mb: 1,
                      }}
                    >
                      <Typography
                        variant="h6"
                        sx={{
                          fontWeight: 700,
                        }}
                      >
                        {item.name}
                      </Typography>

                      <Chip
                        label={
                          item.category
                        }
                        size="small"
                        color="success"
                      />
                    </Box>

                    <Typography
                      color="text.secondary"
                      sx={{ mb: 2 }}
                    >
                      {item.description}
                    </Typography>

                    <Box
                      sx={{
                        display: "flex",
                        justifyContent:
                          "space-between",
                        alignItems:
                          "center",
                      }}
                    >
                      <Typography
                        variant="h6"
                        sx={{
                          fontWeight: 800,
                          color: "#2E7D32",
                        }}
                      >
                        ₹{item.price}
                      </Typography>

                      <Button
                        variant="contained"
                        startIcon={<Add />}
                        onClick={() =>
                          addToCart(item)
                        }
                        sx={{
                          backgroundColor:
                            "#2E7D32",
                        }}
                      >
                        Add
                      </Button>
                    </Box>
                  </CardContent>
                </Card>
              </Grid>
            )
          )}
        </Grid>
      )}
    </>
  );

  // =========================
  // CART
  // =========================
  const renderCart = () => (
    <>
      <Typography
        variant="h4"
        sx={{
          fontWeight: 800,
          color: "#2E7D32",
          mb: 3,
        }}
      >
        My Cart
      </Typography>

      {cart.length === 0 ? (
        <Card
          sx={{
            p: 5,
            textAlign: "center",
          }}
        >
          <ShoppingCart
            sx={{
              fontSize: 60,
              color: "#2E7D32",
              mb: 2,
            }}
          />

          <Typography variant="h6">
            Your cart is empty
          </Typography>

          <Button
            variant="contained"
            sx={{ mt: 2 }}
            onClick={() =>
              setActivePage("menu")
            }
          >
            Browse Menu
          </Button>
        </Card>
      ) : (
        <>
          {cart.map((item) => (
            <Card
              key={item.name}
              sx={{
                mb: 2,
                borderRadius: 3,
              }}
            >
              <CardContent>
                <Grid
                  container
                  alignItems="center"
                  spacing={2}
                >
                  <Grid
                    item
                    xs={12}
                    sm={5}
                  >
                    <Typography
                      variant="h6"
                      sx={{
                        fontWeight: 700,
                      }}
                    >
                      {item.name}
                    </Typography>

                    <Typography color="text.secondary">
                      ₹{item.price} each
                    </Typography>
                  </Grid>

                  <Grid
                    item
                    xs={12}
                    sm={4}
                  >
                    <Box
                      sx={{
                        display: "flex",
                        alignItems:
                          "center",
                        gap: 1,
                      }}
                    >
                      <IconButton
                        onClick={() =>
                          decreaseQuantity(
                            item.name
                          )
                        }
                      >
                        <Remove />
                      </IconButton>

                      <Typography
                        sx={{
                          fontWeight: 700,
                          minWidth: 30,
                          textAlign:
                            "center",
                        }}
                      >
                        {item.quantity}
                      </Typography>

                      <IconButton
                        onClick={() =>
                          increaseQuantity(
                            item.name
                          )
                        }
                      >
                        <Add />
                      </IconButton>
                    </Box>
                  </Grid>

                  <Grid
                    item
                    xs={12}
                    sm={3}
                  >
                    <Typography
                      variant="h6"
                      sx={{
                        fontWeight: 800,
                        color: "#2E7D32",
                      }}
                    >
                      ₹
                      {item.price *
                        item.quantity}
                    </Typography>
                  </Grid>
                </Grid>
              </CardContent>
            </Card>
          ))}

          <Card
            sx={{
              p: 3,
              mt: 3,
            }}
          >
            <Box
              sx={{
                display: "flex",
                justifyContent:
                  "space-between",
                mb: 2,
              }}
            >
              <Typography variant="h6">
                Total
              </Typography>

              <Typography
                variant="h5"
                sx={{
                  fontWeight: 800,
                  color: "#2E7D32",
                }}
              >
                ₹{cartTotal}
              </Typography>
            </Box>

            <Button
              fullWidth
              variant="contained"
              size="large"
              onClick={placeOrder}
              sx={{
                background:
                  "linear-gradient(135deg, #2E7D32, #4CAF50)",
              }}
            >
              PLACE ORDER
            </Button>
          </Card>
        </>
      )}
    </>
  );

  // =========================
  // MY ORDERS
  // =========================
  const renderOrders = () => (
    <>
      <Typography
        variant="h4"
        sx={{
          fontWeight: 800,
          color: "#2E7D32",
          mb: 3,
        }}
      >
        My Orders
      </Typography>

      {loadingOrders ? (
        <Box
          sx={{
            textAlign: "center",
            py: 5,
          }}
        >
          <CircularProgress />
        </Box>
      ) : orders.length === 0 ? (
        <Card
          sx={{
            p: 5,
            textAlign: "center",
          }}
        >
          <ReceiptLong
            sx={{
              fontSize: 60,
              color: "#2E7D32",
            }}
          />

          <Typography
            variant="h6"
            sx={{ mt: 2 }}
          >
            No orders yet
          </Typography>

          <Button
            variant="contained"
            sx={{ mt: 2 }}
            onClick={() =>
              setActivePage("menu")
            }
          >
            Order Food
          </Button>
        </Card>
      ) : (
        orders.map((order) => (
          <Card
            key={order._id}
            sx={{
              mb: 2,
              borderRadius: 3,
            }}
          >
            <CardContent>
              <Box
                sx={{
                  display: "flex",
                  justifyContent:
                    "space-between",
                  flexWrap: "wrap",
                  gap: 2,
                }}
              >
                <Box sx={{ flex: 1 }}>
                  <Typography
                    variant="h6"
                    sx={{
                      fontWeight: 800,
                    }}
                  >
                    {order.itemName}
                  </Typography>

                  <Typography color="text.secondary">
                    Quantity:{" "}
                    {order.quantity}
                  </Typography>

                  <Typography color="text.secondary">
                    ₹
                    {order.price *
                      order.quantity}
                  </Typography>

                  {order.orderNumber && (
                    <Typography
                      color="text.secondary"
                      sx={{ mt: 1 }}
                    >
                      Token:{" "}
                      {order.orderNumber}
                    </Typography>
                  )}
                </Box>

                <Chip
                  label={order.status}
                  color={
                    order.status ===
                      "Served"
                      ? "success"
                      : order.status ===
                        "Preparing"
                        ? "warning"
                        : "info"
                  }
                />
              </Box>

              {/* ========================= */}
              {/* RATE FOOD AFTER SERVED */}
              {/* ========================= */}

              {order.status ===
                "Served" &&
                Array.isArray(
                  order.items
                ) &&
                order.items.length >
                0 && (
                  <Box
                    sx={{
                      mt: 3,
                      pt: 2,
                      borderTop:
                        "1px solid #e0e0e0",
                    }}
                  >
                    <Typography
                      sx={{
                        fontWeight: 700,
                        mb: 2,
                        color:
                          "#2E7D32",
                      }}
                    >
                      Rate your food
                    </Typography>

                    {order.items.map(
                      (food) => {
                        const reviewed =
                          isFoodReviewed(
                            order._id,
                            food.menuItemId
                          );

                        return (
                          <Box
                            key={
                              food.menuItemId
                            }
                            sx={{
                              display:
                                "flex",
                              alignItems:
                                "center",
                              justifyContent:
                                "space-between",
                              gap: 2,
                              flexWrap:
                                "wrap",
                              mb: 1.5,
                              p: 1.5,
                              borderRadius: 2,
                              backgroundColor:
                                "#f7faf7",
                            }}
                          >
                            <Box>
                              <Typography
                                sx={{
                                  fontWeight: 700,
                                }}
                              >
                                {food.name}
                              </Typography>

                              <Typography
                                variant="body2"
                                color="text.secondary"
                              >
                                Quantity:{" "}
                                {
                                  food.quantity
                                }
                              </Typography>
                            </Box>

                            {reviewed ? (
                              <Chip
                                label="Reviewed"
                                color="success"
                                variant="outlined"
                              />
                            ) : (
                              <Button
                                variant="outlined"
                                startIcon={
                                  <RateReview />
                                }
                                onClick={() =>
                                  openReviewDialog(
                                    order,
                                    food
                                  )
                                }
                                sx={{
                                  color:
                                    "#2E7D32",
                                  borderColor:
                                    "#2E7D32",
                                }}
                              >
                                Rate & Review
                              </Button>
                            )}
                          </Box>
                        );
                      }
                    )}
                  </Box>
                )}
            </CardContent>
          </Card>
        ))
      )}
    </>
  );

  // =========================
  // REVIEWS
  // =========================
  const renderReviews = () => (
    <>
      <Typography
        variant="h4"
        sx={{
          fontWeight: 800,
          color: "#2E7D32",
          mb: 3,
        }}
      >
        Reviews
      </Typography>

      {loadingReviews ? (
        <Box
          sx={{
            textAlign: "center",
            py: 5,
          }}
        >
          <CircularProgress />
        </Box>
      ) : reviews.length === 0 ? (
        <Card
          sx={{
            p: 4,
            borderRadius: 3,
          }}
        >
          <RateReview
            sx={{
              fontSize: 60,
              color: "#2E7D32",
              mb: 2,
            }}
          />

          <Typography variant="h6">
            Ratings & Reviews
          </Typography>

          <Typography
            color="text.secondary"
            sx={{ mt: 1 }}
          >
            After a served order, you
            can rate the food and write
            a review.
          </Typography>
        </Card>
      ) : (
        reviews.map((review) => (
          <Card
            key={review._id}
            sx={{
              mb: 2,
              borderRadius: 3,
            }}
          >
            <CardContent>
              <Typography
                variant="h6"
                sx={{
                  fontWeight: 800,
                  color: "#2E7D32",
                }}
              >
                {review.menuItemId
                  ?.name ||
                  "Food Item"}
              </Typography>

              <Rating
                value={review.rating}
                readOnly
                sx={{ my: 1 }}
              />

              {review.comment && (
                <Typography color="text.secondary">
                  {review.comment}
                </Typography>
              )}

              <Typography
                variant="caption"
                color="text.secondary"
              >
                Order:{" "}
                {review.orderId
                  ?.orderNumber ||
                  "Order"}
              </Typography>
            </CardContent>
          </Card>
        ))
      )}
    </>
  );

  // =========================
  // PROFILE
  // =========================
  const renderProfile = () => (
    <>
      <Typography
        variant="h4"
        sx={{
          fontWeight: 800,
          color: "#2E7D32",
          mb: 3,
        }}
      >
        My Profile
      </Typography>

      <Card sx={{ p: 4 }}>
        <Person
          sx={{
            fontSize: 60,
            color: "#2E7D32",
          }}
        />

        <Typography
          variant="h5"
          sx={{ mt: 2 }}
        >
          {user.name}
        </Typography>

        <Typography sx={{ mt: 1 }}>
          Mobile: {user.mobile}
        </Typography>

        <Typography sx={{ mt: 1 }}>
          Account Type: User
        </Typography>
      </Card>
    </>
  );

  // =========================
  // PAGE ROUTER
  // =========================
  const renderPage = () => {
    if (activePage === "home")
      return renderHome();

    if (activePage === "menu")
      return renderMenu();

    if (activePage === "cart")
      return renderCart();

    if (activePage === "orders")
      return renderOrders();

    if (activePage === "reviews")
      return renderReviews();

    if (activePage === "profile")
      return renderProfile();

    return renderHome();
  };

  // =========================
  // NAVIGATION
  // =========================
  const navigate = (page) => {
    setActivePage(page);
    setDrawerOpen(false);
    setOrderMessage("");
    setError("");
  };

  // =========================
  // MAIN UI
  // =========================
  return (
    <Box
      sx={{
        minHeight: "100vh",
        backgroundColor:
          "#f5f7f5",
      }}
    >
      <AppBar
        position="sticky"
        sx={{
          background:
            "linear-gradient(135deg, #2E7D32 0%, #4CAF50 100%)",
        }}
      >
        <Toolbar>
          <IconButton
            color="inherit"
            onClick={() =>
              setDrawerOpen(true)
            }
          >
            <MenuIcon />
          </IconButton>

          <Restaurant
            sx={{ mx: 1 }}
          />

          <Typography
            variant="h5"
            sx={{
              fontWeight: 800,
              flexGrow: 1,
            }}
          >
            CanteenPro
          </Typography>

          <Typography
            sx={{
              mr: 2,
              display: {
                xs: "none",
                sm: "block",
              },
            }}
          >
            Hi, {user.name}
          </Typography>

          <IconButton
            color="inherit"
            onClick={() =>
              navigate("cart")
            }
          >
            <Badge
              badgeContent={
                cartCount
              }
              color="error"
            >
              <ShoppingCart />
            </Badge>
          </IconButton>
        </Toolbar>
      </AppBar>

      <Drawer
        open={drawerOpen}
        onClose={() =>
          setDrawerOpen(false)
        }
      >
        <Box
          sx={{
            width: 280,
          }}
        >
          <Box
            sx={{
              p: 3,
              background:
                "linear-gradient(135deg, #2E7D32, #4CAF50)",
              color: "white",
            }}
          >
            <Typography
              variant="h5"
              sx={{
                fontWeight: 800,
              }}
            >
              CanteenPro
            </Typography>

            <Typography>
              User Panel
            </Typography>
          </Box>

          <List>
            <ListItemButton
              onClick={() =>
                navigate("home")
              }
            >
              <ListItemIcon>
                <Home />
              </ListItemIcon>

              <ListItemText primary="Home" />
            </ListItemButton>

            <ListItemButton
              onClick={() =>
                navigate("menu")
              }
            >
              <ListItemIcon>
                <Restaurant />
              </ListItemIcon>

              <ListItemText primary="Menu" />
            </ListItemButton>

            <ListItemButton
              onClick={() =>
                navigate("cart")
              }
            >
              <ListItemIcon>
                <ShoppingCart />
              </ListItemIcon>

              <ListItemText primary="Cart" />
            </ListItemButton>

            <ListItemButton
              onClick={() =>
                navigate("orders")
              }
            >
              <ListItemIcon>
                <ReceiptLong />
              </ListItemIcon>

              <ListItemText primary="My Orders" />
            </ListItemButton>

            <ListItemButton
              onClick={() =>
                navigate("reviews")
              }
            >
              <ListItemIcon>
                <RateReview />
              </ListItemIcon>

              <ListItemText primary="Reviews" />
            </ListItemButton>

            <ListItemButton
              onClick={() =>
                navigate("profile")
              }
            >
              <ListItemIcon>
                <Person />
              </ListItemIcon>

              <ListItemText primary="Profile" />
            </ListItemButton>

            <Divider />

            <ListItemButton
              onClick={handleLogout}
            >
              <ListItemIcon>
                <Logout color="error" />
              </ListItemIcon>

              <ListItemText
                primary="Logout"
                sx={{
                  color:
                    "error.main",
                }}
              />
            </ListItemButton>
          </List>
        </Box>
      </Drawer>

      <Container
        maxWidth="xl"
        sx={{
          py: 4,
        }}
      >
        {orderMessage && (
          <Alert
            severity="success"
            sx={{ mb: 3 }}
          >
            {orderMessage}
          </Alert>
        )}

        {error && (
          <Alert
            severity="error"
            sx={{ mb: 3 }}
          >
            {error}
          </Alert>
        )}

        {renderPage()}

        {/* ========================= */}
        {/* REVIEW DIALOG */}
        {/* ========================= */}

        <Dialog
          open={reviewDialogOpen}
          onClose={
            closeReviewDialog
          }
          fullWidth
          maxWidth="sm"
        >
          <DialogTitle
            sx={{
              fontWeight: 800,
              color: "#2E7D32",
            }}
          >
            Rate & Review
          </DialogTitle>

          <DialogContent>
            {selectedFood && (
              <Box sx={{ pt: 1 }}>
                <Typography
                  variant="h6"
                  sx={{
                    fontWeight: 700,
                    mb: 2,
                  }}
                >
                  {selectedFood.name}
                </Typography>

                <Typography
                  sx={{
                    mb: 1,
                    fontWeight: 600,
                  }}
                >
                  How was your food?
                </Typography>

                <Rating
                  value={selectedRating}
                  onChange={(
                    event,
                    value
                  ) =>
                    setSelectedRating(
                      value || 0
                    )
                  }
                  size="large"
                  sx={{ mb: 3 }}
                />

                <TextField
                  fullWidth
                  multiline
                  minRows={4}
                  label="Write your review"
                  placeholder="Tell us about the taste, quality, quantity, etc."
                  value={reviewComment}
                  onChange={(event) =>
                    setReviewComment(
                      event.target.value
                    )
                  }
                  inputProps={{
                    maxLength: 500,
                  }}
                  helperText={`${reviewComment.length}/500`}
                />
              </Box>
            )}
          </DialogContent>

          <DialogActions
            sx={{ p: 2 }}
          >
            <Button
              onClick={
                closeReviewDialog
              }
              color="inherit"
              disabled={
                submittingReview
              }
            >
              Cancel
            </Button>

            <Button
              variant="contained"
              onClick={
                submitReview
              }
              disabled={
                submittingReview ||
                selectedRating === 0
              }
              sx={{
                backgroundColor:
                  "#2E7D32",
                "&:hover": {
                  backgroundColor:
                    "#1B5E20",
                },
              }}
            >
              {submittingReview
                ? "Submitting..."
                : "Submit Review"}
            </Button>
          </DialogActions>
        </Dialog>
      </Container>
    </Box>
  );
};

export default UserDashboard;
